1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  payoutForDamages,
9	  settleClaim,
10	  type Damage,
11	} from "./coverage.js";
12	
13	export type { Customer, KnownItemType } from "./pricing.js";
14	export type { Damage } from "./coverage.js";
15	
16	export interface Scenario {
17	  customer: Customer;
18	  steps: Step[];
19	}
20	
21	export interface QuoteStep {
22	  op: "quote";
23	  items: Item[];
24	}
25	
26	export interface ClaimStep {
27	  op: "claim";
28	  policy: number;
29	  incident: { cause: string; damages: Damage[] };
30	}
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export interface ScenarioResults {
35	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
36	}
37	
38	// What earlier steps have established by the time a later step is priced.
39	// Steps are not independent: a quote is a follow-up contract when the customer
40	// already took a quote earlier in the same scenario. Folding this forward —
41	// rather than re-deriving it from the step prefix — is what lets a step read
42	// the state its predecessors left behind.
43	interface Policy {
44	  // The insured items, kept because a claim is settled against them: what a
45	  // damage reimburses depends on the item's own material and enchantment, not
46	  // on the damage entry alone.
47	  items: Item[];
48	  remainingCap: number;
49	}
50	
51	interface ScenarioState {
52	  hasQuoted: boolean;
53	  // Keyed by the step index of the quote that created the policy, which is
54	  // how a later claim step refers to it.
55	  policies: Map<number, Policy>;
56	}
57	
58	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
59	
60	type StepOutcome = ScenarioResults["results"][number];
61	
62	interface StepRun {
63	  outcome: StepOutcome;
64	  state: ScenarioState;
65	}
66	
67	// Every policy a step establishes is recorded the same way, so both handlers
68	// go through here rather than each rebuilding the map.
69	const withPolicy = (
70	  state: ScenarioState,
71	  index: number,
72	  policy: Policy,
73	): ScenarioState => ({
74	  ...state,
75	  policies: new Map(state.policies).set(index, policy),
76	});
77	
78	const runQuote = (
79	  { items }: QuoteStep,
80	  customer: Customer,
81	  state: ScenarioState,
82	  index: number,
83	): StepRun => ({
84	  outcome: {
85	    premium: premiumFor(items, {
86	      customer,
87	      isFollowUpContract: state.hasQuoted,
88	    }),
89	  },
90	  state: withPolicy({ ...state, hasQuoted: true }, index, {
91	    items,
92	    remainingCap: capFor(items),
93	  }),
94	});
95	
96	const runClaim = (
97	  { policy: policyIndex, incident }: ClaimStep,
98	  state: ScenarioState,
99	): StepRun => {
100	  // A claim always names a policy an earlier quote step created. Nothing
101	  // validates that yet — the test rejecting unknown references will force the
102	  // question of what to do when it is absent.
103	  const policy = state.policies.get(policyIndex) ?? {
104	    items: [],
105	    remainingCap: 0,
106	  };
107	  const { payout, remainingCap } = settleClaim(
108	    payoutForDamages(policy.items, incident.damages),
109	    policy.remainingCap,
110	  );
111	
112	  return {
113	    outcome: { payout, remainingCap },
114	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
115	  };
116	};
117	
118	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
119	// so that adding a step kind to the Step union turns "I forgot to handle it"
120	// into a compile error rather than a wrong number.
121	const runStep = (
122	  step: Step,
123	  customer: Customer,
124	  state: ScenarioState,
125	  index: number,
126	): StepRun => {
127	  switch (step.op) {
128	    case "quote":
129	      return runQuote(step, customer, state, index);
130	    case "claim":
131	      return runClaim(step, state);
132	  }
133	};
134	
135	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
136	  const { results } = steps.reduce<{
137	    results: StepOutcome[];
138	    state: ScenarioState;
139	  }>(
140	    ({ results, state }, step, index) => {
141	      const stepRun = runStep(step, customer, state, index);
142	      return { results: [...results, stepRun.outcome], state: stepRun.state };
143	    },
144	    { results: [], state: INITIAL_STATE },
145	  );
146	
147	  return { results };
148	};
